def shapes(grid, region):
    from collections import defaultdict
    cells=defaultdict(list)
    r0,r1=region
    for r in range(r0,r1):
        for c,v in enumerate(grid[r]):
            if v not in (0,5): cells[v].append((r,c))
    out={}
    for v,cs in cells.items():
        rs=[r for r,_ in cs]; cl=[c for _,c in cs]
        rmin,rmax,cmin,cmax=min(rs),max(rs),min(cl),max(cl)
        pat=[[1 if (r,c) in set(cs) else 0 for c in range(cmin,cmax+1)] for r in range(rmin,rmax+1)]
        out[v]=(rmin,cmin,pat)
    return out

def transform(g):
    top=shapes(g,(0,5)); bot=shapes(g,(6,len(g)))
    bcolor=list(bot)[0]; br,bc,bpat=bot[bcolor]
    kept=[]
    for v in sorted(top):
        if v==2: continue
        r,c,pat=top[v]
        if len(pat)>3: continue
        if v==bcolor: continue  # dedupe: top dropped on color dup
        kept.append((v,pat))
    # bottom occupies slot at rows br-6, cols bc..; extras stack above (wrap below if needed)
    slot=br-6
    H=9; W=15
    out=[[0]*W for _ in range(H)]
    def draw(v,pat,r0,c0):
        for i,row in enumerate(pat):
            for j,x in enumerate(row):
                if x: out[r0+i][c0+j]=v
    # place kept shapes: they go contiguously above the slot; wrap below if start<0
    n=len(kept)
    start=slot-3*n
    if start<0:
        draw(bcolor,bpat,slot,bc)
        rr=slot+3
        for v,pat in kept:
            draw(v,pat,rr,bc); rr+=3
    else:
        rr=start
        for v,pat in kept:
            draw(v,pat,rr,bc); rr+=3
        draw(bcolor,bpat,slot,bc)
    return out

